import test from "node:test";
import assert from "node:assert/strict";
import {planner, apply} from "./replay.mjs";

const catalog = {default: 5, studios: new Map([["orchid", 8], ["iris", 3]])};
const booking = (id, units, overrides = {}) => ({
  service: "studio", action: "book", tenant: "orchid", day: "2025-04-02",
  id, units, ...overrides
});

test("Studio applies tenant/day quotas including lower allocations and defaults", () => {
  const dispatch = planner(catalog);
  assert.deepEqual(dispatch(booking("first", 7)), {status:"booked", id:"first", remaining:1});
  assert.equal(dispatch(booking("too-many", 2)).status, "full");
  assert.equal(dispatch(booking("last", 1)).remaining, 0);
  assert.equal(dispatch(booking("tomorrow", 8, {day:"2025-04-03"})).status, "booked");
  assert.equal(dispatch(booking("iris-full", 4, {tenant:"iris"})).status, "full");
  assert.equal(dispatch(booking("iris-ok", 3, {tenant:"iris"})).remaining, 0);
  assert.equal(dispatch(booking("default-full", 6, {tenant:"rose"})).status, "full");
  assert.equal(dispatch(booking("default-ok", 5, {tenant:"rose"})).remaining, 0);
  assert.equal(dispatch(booking("archive-full", 6, {service:"archive"})).status, "full");
  assert.equal(dispatch(booking("archive-ok", 5, {service:"archive"})).remaining, 0);
});

test("replays, conflicts, cancellations and imports retain journal semantics", () => {
  const dispatch = planner(catalog);
  const request = booking("original", 8);
  dispatch(request);
  assert.equal(dispatch(request).status, "replay");
  assert.equal(dispatch({...request, units:9}).status, "conflict");
  const cancel = {action:"cancel", service:"studio", id:request.id};
  assert.equal(dispatch(cancel).status, "cancelled");
  assert.equal(dispatch(cancel).status, "replay");
  assert.equal(dispatch(request).status, "cancelled");
  assert.equal(dispatch(booking("replacement", 8)).status, "booked");
  assert.deepEqual(dispatch({action:"usage", service:"studio", tenant:"orchid", day:request.day}), {units:8});
  assert.equal(dispatch(booking("backfill", 12, {action:"import", day:"2025-04-04"})).status, "imported");
  assert.deepEqual(dispatch(booking("overfilled", 1, {day:"2025-04-04"})),
    {status:"full", id:"overfilled", remaining:0});
  const summary = dispatch({action:"summary", service:"studio"});
  assert.equal(summary.occupied.length, 2);
  assert.equal(summary.events.length, 4);
  assert.deepEqual(apply(dispatch, booking("invalid", 0)), {status:"invalid", field:"units"});
});

test("monthly renewals use the same Studio policy and inherit the previous tenant", () => {
  const dispatch = planner(catalog);
  dispatch(booking("original", 7));
  const renewal = {service:"studio", action:"renew", previous:"original", id:"renewal", day:"2025-05-02", tenant:"iris"};
  assert.deepEqual(dispatch(renewal), {status:"booked", id:"renewal", remaining:1});
  assert.equal(dispatch(renewal).status, "replay");
  assert.equal(dispatch({...renewal, units:6}).status, "conflict");
  assert.equal(dispatch({...renewal, id:"too-many", units:2}).status, "full");
  assert.equal(dispatch({...renewal, id:"last", units:1}).remaining, 0);
  dispatch({service:"studio", action:"cancel", id:"renewal"});
  assert.equal(dispatch(renewal).status, "cancelled");
  dispatch({service:"studio", action:"cancel", id:"original"});
  assert.equal(dispatch({...renewal, id:"missing"}).status, "missing");
  dispatch(booking("default", 5, {tenant:"rose"}));
  assert.equal(dispatch({...renewal, previous:"default", id:"default-next", units:6}).status, "full");
  dispatch(booking("archive", 5, {service:"archive"}));
  assert.equal(dispatch({...renewal, service:"archive", previous:"archive", id:"archive-next", units:6}).status, "full");
});
